mapper.sql:
h.deleted = 0
AND (
    #{admin} = TRUE
    OR h.teacher_user_id = #{currentUserId}
    OR (
        h.status IN ('PUBLISHED', 'CLOSED')
        AND EXISTS (
            SELECT 1
            FROM assessment_homework_recipient recipient
            WHERE recipient.homework_id = h.id
              AND recipient.student_user_id = #{currentUserId}
        )
    )
)

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM assessment_homework_recipient
    WHERE homework_id = #{homeworkId} AND student_user_id = #{studentUserId}
)
